const body = $input.first().json;

const questionType = body.questionType || 'mcq';

const typeInstruction =
  questionType === 'closed_ended'
    ? 'Generate close-ended questions with one correct short answer.'
    : 'Generate multiple choice questions with exactly four options and one correct answer.';

const prompt = `
You are Learnify Quiz Generator (strict educational AI).

IMPORTANT RULE:
Use ONLY the Curriculum Context and Scanned Note below.
Do NOT use external knowledge outside provided context.

---

Subject: ${body.subject || ''}
Topic: ${body.topic || ''}
Question Type: ${questionType}

---

CURRICULUM CONTEXT (PRIMARY SOURCE - MUST PRIORITIZE):
${body.curriculumContext || 'No curriculum context available.'}

---

STUDENT NOTE CONTEXT:
${body.extractedText || 'No scanned note provided.'}

---

TASK:
${typeInstruction}

---

STRICT OUTPUT RULES:
- Output ONLY valid JSON (no markdown, no explanations, no backticks)
- Generate exactly 10 questions
- Each question must strictly follow WAEC / NECO / JAMB standard
- Do NOT repeat questions
- Do NOT hallucinate facts not present in context

---

JSON SCHEMA:
{
  "studentId": "${body.studentId || ''}",
  "noteId": "${body.noteId || ''}",
  "subject": "${body.subject || ''}",
  "topic": "${body.topic || ''}",
  "questionType": "${questionType}",
  "ragChunksUsed": ${body.ragChunksFound || 0},
  "questions": [
    {
      "question": "",
      "options": [],
      "correctAnswer": "",
      "explanation": "",
      "type": "${questionType}"
    }
  ]
}
`;

return [{ json: { ...body, prompt } }];

