const response = $input.first().json;

let text =
  response?.candidates?.[0]?.content?.parts?.[0]?.text ||
  '';

if (!text) {
  throw new Error('Empty response from Gemini');
}

// ─────────────────────────────
// CLEAN CODE BLOCKS SAFELY
// ─────────────────────────────
text = text
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/^\s*json\s*/gi, '')
  .trim();

// ─────────────────────────────
// SAFE JSON PARSE
// ─────────────────────────────
let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error(
    'Gemini JSON parse failed. Check prompt or model output format.'
  );
}

// ─────────────────────────────
// OUTPUT
// ─────────────────────────────
return [{ json: parsed }];

// body arrives with curriculumContext already injected by the RAG pipeline
const body = $input.item.json;

const prompt = `
You are Learnify Study Planner.

Create a practical, curriculum-aligned study plan for a student.

Subject: ${body.subject}
Topic: ${body.topic}
Exam Date: ${body.examDate}
Available Hours Per Day: ${body.availableHoursPerDay}

Curriculum Context (Retrieved from Google Drive RAG – prioritise this):
${body.curriculumContext || 'No curriculum context available.'}

Scanned Note:
${body.extractedText || 'No scanned note provided.'}

Return valid JSON only in this format:
{
  "studentId": "${body.studentId}",
  "noteId": "${body.noteId}",
  "examDate": "${body.examDate}",
  "availableHoursPerDay": ${Number(body.availableHoursPerDay || 1)},
  "ragChunksUsed": ${body.ragChunksFound || 0},
  "plan": [
    { "day": "Day 1", "subject": "${body.subject}", "topic": "${body.topic}", "durationMinutes": 30, "task": "Study key concept and answer practice questions" }
  ]
}

Rules:
- Create 7 days of study tasks.
- Prioritise topics and subtopics from the Curriculum Context.
- Include revision days and timed practice sessions.
- Align content with WAEC/NECO/JAMB exam requirements.
- Do not include markdown.
`;
return [{ json: { ...body, prompt } }];

const response = $input.first().json;
let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
text = text.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(text); } catch (error) { throw new Error('Gemini did not return valid study plan JSON: ' + text); }
return [{ json: parsed }];

const input = $input.first().json;

const sourceText = input.text || input.content || '';

if (!sourceText.trim()) {
  throw new Error(`No text. Fields: ${Object.keys(input).join(', ')}`);
}

const fileName       = input.fileName || input.sourceName || 'WAEC_General_General.pdf';
const parts          = fileName.replace('.pdf', '').split('_');
const curriculumType = parts[0] || 'WAEC';
const subject        = parts[1] || 'General';
const topic          = parts[2] || 'General';

return [{
  json: {
    sourceText,
    curriculumType,
    subject,
    topic,
    level:          'SS',
    sourceName:     fileName,
    sourceFileId:   input.fileId   || '',
    sourceMimeType: input.mimeType || 'application/pdf',
  }
}];

const body = $input.first().json;

const sourceText =
  body.sourceText    ||
  body.text          ||
  body.content       ||
  body.extractedText ||
  body.data          ||
  '';

if (!sourceText.trim()) {
  throw new Error(`Empty. Fields: ${Object.keys(body).join(', ')}`);
}

const text = sourceText
  .replace(/\r/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

const chunkSize  = 800;
const overlap    = 120;
const MAX_CHUNKS = 20;
const output     = [];
let start = 0;
let index = 0;

while (start < text.length && output.length < MAX_CHUNKS) {
  const end   = Math.min(start + chunkSize, text.length);
  const chunk = text.slice(start, end).trim();

  if (chunk.length > 50) {
    output.push({
      json: {
        curriculumType: body.curriculumType,
        subject:        body.subject,
        topic:          body.topic,
        level:          body.level,
        sourceName:     body.sourceName,
        sourceFileId:   body.sourceFileId,
        sourceMimeType: body.sourceMimeType,
        chunkIndex:     index,
        chunkText:      chunk,
      }
    });
    index++;
  }

  start = end - overlap;
  if (start < 0) start = end;
}

return output;

const source = $node["Code - Split Curriculum Chunks"].json;

const response = $input.first().json;

// ─────────────────────────────
// SAFE EMBEDDING EXTRACTION
// ─────────────────────────────
const embedding =
  response?.embedding?.values ||
  response?.embedding ||
  response?.data?.embedding ||
  [];

// ─────────────────────────────
// VALIDATION
// ─────────────────────────────
if (!Array.isArray(embedding) || embedding.length === 0) {
  throw new Error('Invalid embedding returned from Gemini.');
}

// ─────────────────────────────
// OPTIONAL: BASIC VECTOR SANITY CHECK
// ─────────────────────────────
const isValidVector = embedding.every(v => typeof v === 'number');

if (!isValidVector) {
  throw new Error('Embedding contains non-numeric values.');
}

// ─────────────────────────────
// OUTPUT
// ─────────────────────────────
return [
  {
    json: {
      ...source,
      embedding
    }
  }
];

const input = $node["Webhook - RAG Query"].json;

const body = input.body ?? input;

if (!body.question?.trim()) {
  throw new Error("Missing required field: question");
}

return [
  {
    json: {
      ...body,
      curriculumType: body.curriculumType || "WAEC",
      mode: body.mode || "tutor",
