const response = $input.first().json;

const embedding =
  response?.embedding?.values ||
  response?.embedding ||
  [];

if (!Array.isArray(embedding) || embedding.length === 0) {
  throw new Error("No query embedding returned from Gemini.");
}

return [
  {
    json: {
      ...query,
      embedding,
      limit: query.limit || 5
    }
  }
