const query = $node["Code - Validate RAG Query"].json;

const result = $input.first().json;

const chunks =
  result.data ||
  result.matches ||
  result.results ||
  [];

const context = Array.isArray(chunks)
  ? chunks
      .map(
        (item, index) =>
          `SOURCE ${index + 1}:\n${item.chunkText || item.text || item.content || ""}`
      )
      .join("\n\n")
  : "";

let task =
  "Answer like a patient AI tutor. Provide a simple explanation, step-by-step breakdown, one example, and one practice question.";

if (query.mode === "quiz") {
  task =
    "Generate quiz questions using only the retrieved curriculum context.";
}

if (query.mode === "planner") {
  task =
    "Create a study plan using only the retrieved curriculum context.";
}

const prompt = `
You are Learnify, a curriculum-aware educational AI.

Curriculum: ${query.curriculumType}
Subject: ${query.subject || ""}
Topic: ${query.topic || ""}
Mode: ${query.mode}

RETRIEVED CURRICULUM CONTEXT:
${context || "No curriculum context found."}

STUDENT REQUEST:
${query.question}

TASK:
${task}

RULES:
- Use the retrieved curriculum context as your primary source.
- Do not invent facts that are not supported by the context.
- If the context is insufficient, clearly state what information is missing.
- Keep explanations student-friendly and age-appropriate.
- For tutor mode, include:
  1. Simple Explanation
  2. Step-by-Step Breakdown
  3. Example
  4. Practice Question
`;

return [
  {
    json: {
      ...query,
      prompt,
      context,
      retrievedChunks: chunks.length
    }
  }
];

const answer = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || 'No answer generated.';

return [
  {
    json: {
      success: true,
      answer
    }
  }
];

