const webhookBody =
  $node["Webhook - Quiz Generator"].json?.body ||
  $node["Webhook - Quiz Generator"].json ||
  {};

// ─────────────────────────────────────────────
// SAFE RAG RESPONSE EXTRACTION
// ─────────────────────────────────────────────
const result = $input.first().json;

const chunks = Array.isArray(result?.data)
  ? result.data
  : Array.isArray(result?.matches)
  ? result.matches
  : Array.isArray(result?.results)
  ? result.results
  : [];

// ─────────────────────────────────────────────
// BUILD CURRICULUM CONTEXT
// ─────────────────────────────────────────────
let curriculumContext = '';

if (chunks.length > 0) {
  curriculumContext = chunks
    .map((item, i) => {
      const text =
        item.chunkText ||
        item.text ||
        item.content ||
        '';

      return text.trim()
        ? `[${i + 1}] ${text.trim()}`
        : null;
    })
    .filter(Boolean)
    .join('\n\n');
} else {
  curriculumContext = 'No relevant RAG context found.';
}

// ─────────────────────────────────────────────
// FINAL OUTPUT
// ─────────────────────────────────────────────
return [
  {
    json: {
      ...webhookBody,
      curriculumContext,
      ragChunksFound: chunks.length,
      ragInjected: chunks.length > 0
    }
  }
];

