const item = $input.first().json;

// ─────────────────────────────
// SAFE WEBHOOK ACCESS
// ─────────────────────────────
const body = $node["Webhook - OCR1"].json?.body || $node["Webhook - OCR1"].json || {};

// ─────────────────────────────
// DETECT SOURCE SAFELY
// ─────────────────────────────
let rawText = '';
let source = item.source || 'unknown';

// TEXT PATH (paste)
if (typeof item.rawText === "string") {
  rawText = item.rawText;
  source = 'paste';

// GEMINI PATH (URL / Upload)
} else {
  rawText =
    item?.candidates?.[0]?.content?.parts?.[0]?.text ||
    item?.text ||
    '';
  source = item.source || 'gemini-ocr';
}

// ─────────────────────────────
// SAFE CLEANING
// ─────────────────────────────
const cleaned = (rawText || '')
  .replace(/\r\n|\r/g, '\n')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/- \n/g, '')
  .trim();

// ─────────────────────────────
// SAFE WORD COUNT
// ─────────────────────────────
const wordCount = cleaned
  ? cleaned.split(/\s+/).filter(Boolean).length
  : 0;

// ─────────────────────────────
// FINAL OUTPUT
// ─────────────────────────────
return [
  {
    json: {
      noteId: body.noteId || item.noteId || null,
      userId: body.userId || item.userId || null,
      extractedText: cleaned,
      wordCount,
      inputType: body.inputType || item.inputType || 'unknown',
      source
    }
  }
];
